// ─── File: VarcharDemo.java ───
// Shows when a BYTE-sized column rejects a name a CHAR-sized column accepts.
package com.bank.varchar;

import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.logging.*;

public class VarcharDemo {
    private static final Logger log = Logger.getLogger(VarcharDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        NameValidationService service = new NameValidationService();

        ColumnSpec byte10 = new ColumnSpec(10, LengthSemantics.BYTE);
        ColumnSpec char10 = new ColumnSpec(10, LengthSemantics.CHAR);

        String english = "Rajesh";          // 6 chars, 6 UTF-8 bytes
        String hindi   = "राजेश";            // 5 chars, 15 UTF-8 bytes (3 bytes each)

        log.info("=== English name 'Rajesh' ===");
        check(service, byte10, english);
        check(service, char10, english);

        log.info("=== Hindi name 'राजेश' (multi-byte) ===");
        check(service, byte10, hindi);       // fails on BYTE
        check(service, char10, hindi);       // fits on CHAR
    }

    private static void check(NameValidationService service, ColumnSpec spec, String name) {
        boolean ok = service.fits(spec, name);
        int chars = name.codePointCount(0, name.length());
        int bytes = name.getBytes(StandardCharsets.UTF_8).length;
        String msg = "VARCHAR2(" + spec.length + " " + spec.semantics + ") name='" + name
            + "' chars=" + chars + " bytes=" + bytes + " → " + (ok ? "FITS" : "REJECTED");
        if (ok) log.info(msg); else log.severe(msg);
    }
}

// ─── Would be in model/LengthSemantics.java ───
enum LengthSemantics { BYTE, CHAR }

// ─── Would be in model/ColumnSpec.java ───
class ColumnSpec {
    final int length; final LengthSemantics semantics;
    ColumnSpec(int length, LengthSemantics semantics) {
        this.length = length; this.semantics = semantics;
    }
}

// ─── Would be in service/NameValidationService.java ───
class NameValidationService {
    // Returns true if the value fits the column under its declared semantics.
    boolean fits(ColumnSpec spec, String value) {
        if (spec.semantics == LengthSemantics.CHAR) {
            int chars = value.codePointCount(0, value.length()); // count characters
            return chars <= spec.length;
        } else { // BYTE semantics: count UTF-8 bytes
            int bytes = value.getBytes(StandardCharsets.UTF_8).length;
            return bytes <= spec.length;
        }
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
